from pathlib import Path
import json,shutil
N=Path(__file__).resolve().parent;ROOT=N.parents[2]
# Main entry points and ordinary area/editor shortcuts all use the same runtime.
routes={'Launch_Valwood_Demo.sh': ('demo', []), 'Launch_Valwood_Demo_Fixed.sh': ('demo', []), 'Launch_Valwood_Opening.sh': ('demo', []), 'Launch_Valwood_Journey_Demo.sh': ('demo', []), 'Launch_Polished_Demo.sh': ('demo', []), 'Launch_Valwood_Authored_Demo.sh': ('demo', []), 'Launch_Valwood_NPC_Intro.sh': ('demo', []), 'Launch_Valwood_Busy_Road_Demo.sh': ('demo', []), 'Launch_Valwood_Polished_Road_Demo.sh': ('demo', []), 'Launch_Valwood_Editor.sh': ('editor', []), 'Launch_Valwood_Cinematic_Editor.sh': ('editor', ['--cinematics']), 'Launch_Valwood_Visual_Editor.sh': ('editor', ['--area', 'showcase']), 'Launch_Valwood_Quality_Editor.sh': ('editor', []), 'Launch_Valwood_City_Editor.sh': ('editor', ['--area', 'city']), 'Launch_Valwood_Stronghold_Editor.sh': ('editor', ['--area', 'grandstone']), 'Launch_Studio.sh': ('editor', []), 'Launch_Valwood_Arena.sh': ('arena', []), 'Launch_Valwood_Arena_Visual.sh': ('arena', []), 'Launch_Valwood_Arena_Final.sh': ('arena', []), 'Launch_Valwood_Arena_Restored.sh': ('arena', []), 'Launch_Valwood_Combat_Arena.sh': ('arena', []), 'Launch_Valwood_Joust.sh': ('joust', []), 'Launch_Valwood_World.sh': ('world', []), 'Launch_Valwood_Presentation.sh': ('world', ['--area', 'showcase', '--scenic', 'castle-quarter']), 'Launch_Valwood_City.sh': ('world', ['--area', 'city']), 'Launch_Valwood_Countryside.sh': ('world', ['--area', 'city', '--scenic', 'city-meadow']), 'Launch_Valwood_Jungle.sh': ('world', ['--area', 'showcase', '--scenic', 'rainforest-milestone']), 'Launch_Valwood_Rainforest.sh': ('world', ['--area', 'atlas', '--scenic', 'rainforest']), 'Launch_Valwood_Stronghold.sh': ('world', ['--area', 'grandstone']), 'Launch_Valwood_Starting_Area.sh': ('world', ['--scenic', 'seldonne-arrival']), 'Launch_Valwood_Arena_Characters.sh': ('arena', []), 'Launch_Valwood_Animals.sh': ('world', ['--area', 'atlas', '--scenic', 'wildlife-farm', '--no-hud']), 'Launch_Valwood_Bandit_Camp.sh': ('world', ['--area', 'atlas', '--scenic', 'bandit-camp', '--no-hud']), 'Launch_Valwood_Castle_Streets.sh': ('world', ['--area', 'atlas', '--scenic', 'castle-tavern', '--no-hud']), 'Launch_Valwood_Castle_Village.sh': ('world', ['--area', 'atlas', '--scenic', 'castle-alley']), 'Launch_Valwood_Cinematic_Lighting.sh': ('world', ['--area', 'atlas', '--scenic', 'castle-hero-entry', '--no-hud']), 'Launch_Valwood_Dragons.sh': ('world', ['--area', 'atlas', '--scenic', 'castle-frost-dragon', '--no-hud']), 'Launch_Valwood_Environment.sh': ('world', ['--area', 'atlas', '--scenic', 'castle-purchased-gardens', '--no-hud']), 'Launch_Valwood_Gate_Watch.sh': ('world', ['--area', 'atlas', '--scenic', 'castle-watch', '--no-hud']), 'Launch_Valwood_Particles.sh': ('world', ['--area', 'atlas', '--scenic', 'castle-hero-entry', '--no-hud']), 'Launch_Valwood_Rainforest_Showcase.sh': ('world', ['--area', 'atlas', '--scenic', 'rainforest-pool']), 'Launch_Valwood_Training.sh': ('world', ['--area', 'atlas', '--scenic', 'castle-training-start', '--no-hud'])}
staged=N/'staged-launchers';old=N/'previous-launchers';staged.mkdir(exist_ok=True);old.mkdir(exist_ok=True)
for name,(mode,extra) in routes.items():
 previous=ROOT/name
 if previous.exists() and not (old/name).exists():shutil.copy2(previous,old/name)
 suffix=' '.join([mode,*extra])
 text='#!/usr/bin/env bash\nset -euo pipefail\nvalwood_root=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)\nexec python3 "$valwood_root/new_engine/run_current_valwood.py" '+suffix+' "$@"\n'
 (staged/name).write_text(text);(staged/name).chmod(0o755)
name='Launch_Valwood.sh'
(staged/name).write_text('#!/usr/bin/env bash\nset -euo pipefail\nvalwood_root=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)\nexec python3 "$valwood_root/new_engine/run_current_valwood.py" "$@"\n');(staged/name).chmod(0o755)
routes[name]=('mode selector',[])
for name,verb in (('Import_Valwood_Cutscene_Voice.sh','import-cutscene-voice'),('Import_Valwood_NPC_Voice.sh','import-npc-voice')):
 previous=ROOT/name
 if previous.exists() and not (old/name).exists():shutil.copy2(previous,old/name)
 (staged/name).write_text('#!/usr/bin/env bash\nset -euo pipefail\nvalwood_root=$(cd -- \"$(dirname -- \"${BASH_SOURCE[0]}\")\" && pwd)\nexec python3 \"$valwood_root/new_engine/run_current_valwood.py\" '+verb+' \"$@\"\n')
 (staged/name).chmod(0o755);routes[name]=(verb,[])
(N/'WRAPPERS.json').write_text(json.dumps(routes,indent=2)+'\n')
print('Prepared',len(routes),'shared-runtime entry points; originals archived; not promoted yet.')
